}

:root {
  --bg-page:        #0d1117;
  --bg-card:        #161b22;
  --bg-card-border: #30363d;
  --bg-input:       #0d1117;
  --text-primary:   #e6edf3;
  --text-muted:     #8b949e;
  --accent:         #58a6ff;
  --accent-hover:   #79b8ff;
  --accent-active:  #388bfd;
  --danger:         #f85149;
  --success:        #3fb950;
  --btn-bg:         #238636;
  --btn-bg-hover:   #2ea043;
  --btn-bg-active:  #1a7f37;
  --btn-border:     #3fb950;
  --btn-text:       #ffffff;
  --focus-ring:     #58a6ff;
  --radius-md:      8px;
  --radius-sm:      4px;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Helvetica, Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--accent);
  color: var(--bg-page);
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

/* ── Card ───────────────────────────────────────────────────── */
.consent-card {
  background: var(--bg-card);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-md);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
}

.consent-card__header {
  margin-bottom: 1.75rem;
}

.consent-card__title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.consent-card__subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* ── Form ───────────────────────────────────────────────────── */
.consent-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ── Checkbox field ─────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-field__label {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  cursor: pointer;
  font-size: 0.9375rem;
  color: var(--text-primary);
}

/* visually-hidden native checkbox — replaced by styled box */
.form-field__input {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Custom checkbox box */
.form-field__checkbox-box {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: 0.175rem;          /* optical alignment with first text line */
  border: 2px solid var(--bg-card-border);
  border-radius: var(--radius-sm);
  background: var(--bg-input);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.15s, background-color 0.15s;
}

.form-field__checkbox-box svg {
  display: none;
  fill: none;
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Checked state */
.form-field__input:checked + .form-field__label .form-field__checkbox-box {
  background: var(--accent);
  border-color: var(--accent);
}
.form-field__input:checked + .form-field__label .form-field__checkbox-box svg {
  display: block;
}

/* Focus-visible ring */
.form-field__input:focus-visible + .form-field__label .form-field__checkbox-box {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

