.form-field__input[aria-invalid="true"] + .form-field__label .form-field__checkbox-box {
  border-color: var(--danger);
}

.form-field__label-text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-field__label-main {
  color: var(--text-primary);
}

.form-field__label-main a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.form-field__label-main a:hover {
  color: var(--accent-hover);
}
.form-field__label-main a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}

.required-indicator {
  color: var(--danger);
  margin-left: 0.1em;
  aria-hidden: true;
}

/* Helper / error text */
.form-field__helper {
  font-size: 0.8125rem;
  color: var(--text-muted);
  padding-left: calc(1.125rem + 0.75rem); /* align with label text */
}

.form-field__error {
  font-size: 0.8125rem;
  color: var(--danger);
  padding-left: calc(1.125rem + 0.75rem);
  display: none;
}
.form-field__error[aria-live] {
  display: block;
}
.form-field__error:empty {
  display: none;
}

/* ── Submit button ──────────────────────────────────────────── */
.consent-form__actions {
  display: flex;
  justify-content: flex-end;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--btn-bg);
  border: 1px solid var(--btn-border);
  border-radius: var(--radius-md);
  color: var(--btn-text);
  cursor: pointer;
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 0.5rem 1.25rem;
  transition: background-color 0.15s, border-color 0.15s;
  /* Ensure contrast in forced-colors */
  outline: transparent 2px solid;
  outline-offset: 2px;
}
.btn-submit:hover {
  background: var(--btn-bg-hover);
}
.btn-submit:active {
  background: var(--btn-bg-active);
}
.btn-submit:focus-visible {
  outline-color: var(--focus-ring);
}
.btn-submit[aria-busy="true"] {
  opacity: 0.7;
  cursor: wait;
}

/* ── Status message ─────────────────────────────────────────── */
.consent-form__status {
  font-size: 0.9rem;
  padding: 0.6rem 0.875rem;
  border-radius: var(--radius-sm);
  display: none;
}
.consent-form__status--success {
  display: block;
  background: rgba(63, 185, 80, 0.12);
  border: 1px solid var(--success);
  color: var(--success);
}
.consent-form__status--error {
  display: block;
  background: rgba(248, 81, 73, 0.12);
  border: 1px solid var(--danger);
  color: var(--danger);
}

/* ── Forced colors ──────────────────────────────────────────── */
@media (forced-colors: active) {
  .form-field__checkbox-box {
    border-color: ButtonBorder;
