  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

